class Solution {
    public String largestGoodInteger(String num){
        char best=0;
        for(int i=0;i+2<num.length();i++)if(num.charAt(i)==num.charAt(i+1)&&num.charAt(i)==num.charAt(i+2))best=(char)Math.max(best,num.charAt(i));
        return best==0?"":String.valueOf(best).repeat(3);
    }
}

code.kotlin:
class Solution {
    fun largestGoodInteger(num:String):String{
        var best:Char?=null;
        for(i in 0 until num.length-2)if(num[i]==num[i+1]&&num[i]==num[i+2]&&(best==null||num[i]>best!!))best=num[i];
        return best?.toString()?.repeat(3)?:""
    }
}

